fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mid: i32 = h / 2;
    let amp: i32 = h / 3;
    host::display::clear(0x0a0a0a);
    host::display::draw_line(0, mid, w - 1, mid, 0x505050);
    host::display::draw_line(16, mid - amp - 10, 16, mid + amp + 10, 0x505050);
    let mut k: i32 = 0;
    while k < 9 {
        host::display::draw_line(k * (w - 1) / 8, mid - 3, k * (w - 1) / 8, mid + 3, 0x808080);
        k = k + 1;
    }
    host::display::draw_line(12, mid - amp, 20, mid - amp, 0x808080);
    host::display::draw_line(12, mid + amp, 20, mid + amp, 0x808080);
    let mut i: i32 = 0;
    while i < 63 {
        let x0: i32 = i * (w - 1) / 63;
        let x1: i32 = (i + 1) * (w - 1) / 63;
        host::display::draw_line(x0, mid - sv(i) * amp / 127, x1, mid - sv(i + 1) * amp / 127, 0x40ff80);
        host::display::draw_line(x0, mid - sv(i + 8) * amp / 127, x1, mid - sv(i + 9) * amp / 127, 0xff8040);
        i = i + 1;
    }
    host::display::fill_rect(w - 90, 12, 10, 10, 0x40ff80);
    host::display::draw_string(w - 74, 12, "SIN", 0xc0c0c0, 1);
    host::display::fill_rect(w - 90, 28, 10, 10, 0xff8040);
    host::display::draw_string(w - 74, 28, "COS", 0xc0c0c0, 1);
    host::display::present();
}
